    // Devolver = Libros regresan a circulación.
    queryEjemplares = `UPDATE ejemplares SET estado = 'disponible' WHERE id IN (SELECT ejemplar_id FROM prestamos WHERE usuario_id = ${d.usuario_id} AND estado = 'activo');`;
    queryPrestamos = `UPDATE prestamos SET estado = 'devuelto', fecha_devolucion_real = CURRENT_TIMESTAMP WHERE usuario_id = ${d.usuario_id} AND estado = 'activo';`;
    mensajeLog = 'Libros devueltos a inventario y usuario reactivado';
} else {
    msg.payload = { ok: false, error: 'Acción no válida' };
    msg.statusCode = 400;
    return msg;
}

// Ejecutamos la transacción completa
msg.query = `BEGIN;
${queryEjemplares}
${queryPrestamos}
UPDATE usuarios SET activo = 1 WHERE id = ${d.usuario_id};
INSERT INTO audit_log (tipo, origen, usuario_id, mensaje) 
    VALUES ('desbaneo', 'api', ${d.usuario_id}, '${mensajeLog}');
COMMIT;`;

// Preparamos la respuesta de éxito que Node-RED enviará al cliente
msg.payload = {
    ok: true,
    mensaje: mensajeLog
};
msg.statusCode = 200;

return msg;

const d = msg.ban_usuario;
msg.payload = {
    ok: true,
    mensaje: `Usuario ${d.nombre} ${d.apellido} desbaneado correctamente`,
    usuario: d
};
msg.statusCode = 200;
return msg;

flow.set('ultimo_rfid', null);
flow.set('rfid_ts', null);
flow.set('usuario_activo', null);
msg.payload = { ok: true };
return msg;

const d = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;

if (!d || !d.usuario_id) {
    msg.payload = { ok: false, error: 'usuario_id requerido' };
    msg.statusCode = 400;
    return [null, msg];
}

msg.ban_data = d;

const diasDeuda = d.vencimiento_mas_antiguo
    ? Math.ceil((Date.now() - new Date(d.vencimiento_mas_antiguo).getTime()) / 86400000)
    : '?';

const prompt = `Eres el sistema de la Biblioteca Universitaria BiblioSys.
Redacta un correo electrónico formal pero con un tono memorable (puede tener un poco de dramatismo cortés) notificando al usuario que su acceso ha sido SUSPENDIDO por préstamos vencidos.

Datos del usuario:
- Nombre: ${d.nombre} ${d.apellido}
- Tipo de usuario: ${d.tipo_usuario}
- Email: ${d.email}
- Libros pendientes: ${d.libros_pendientes || 'no especificados'}
- Préstamos vencidos: ${d.prestamos_vencidos}
- Días de atraso máximo: ${diasDeuda} días

El correo debe:
1. Saludar formalmente usando el nombre completo
2. Mencionar específicamente los libros que no ha devuelto
3. Indicar que el acceso está suspendido hasta regularizar
4. Dar instrucciones claras para reactivar (devolver libros en biblioteca)
5. Firmar como "Sistema BiblioSys - Biblioteca Universitaria"

Solo devuelve el correo, sin explicaciones adicionales.`;

const apiKey = env.get('GEMINI_API_KEY') || '';
msg.url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`;
msg.method = "POST";
msg.headers = {
    "Content-Type": "application/json"
};
msg.payload = {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.8, maxOutputTokens: 600 }
};

return [msg, null];

const tipo = msg.payload.tipo || 'manual';
const ahora = new Date();
const timestamp = ahora.toISOString()
    .replace(/[:.]/g, '-')
    .replace('T', '_')
    .substring(0, 19);

const BACKUP_DIR = env.get('BACKUP_DIR') || '/data/backups';
const MAX_BACKUPS = parseInt(env.get('MAX_BACKUPS') || '30');

const backupFile = `${BACKUP_DIR}/bibliosys_${tipo}_${timestamp}.sql`;

// Comando pg_dump apuntando al host 'postgres'
msg.payload = [
    `mkdir -p ${BACKUP_DIR}`,
    `PGPASSWORD="tu_password_seguro" pg_dump -h postgres -U admin_biblioteca -d bibliosys -F p > ${backupFile}`,
    `gzip -9 ${backupFile}`,
    `ls -t ${BACKUP_DIR}/bibliosys_*.sql.gz | tail -n +${MAX_BACKUPS + 1} | xargs -r rm --`
].join(' && ');

msg.backup_meta = { tipo, timestamp, archivo: backupFile + '.gz' };
node.log(`Iniciando backup Postgres ${tipo}: ${backupFile}.gz`);
return msg;

const meta = msg.backup_meta || {};
msg.query = `INSERT INTO audit_log (tipo, origen, mensaje)
    VALUES ('backup', 'sistema', 'Respaldo ${meta.tipo || ''} completado: ${meta.archivo || ''}');`;
node.status({ fill: 'green', shape: 'dot', text: `OK ${meta.timestamp}` });
node.log(`Backup completado: ${meta.archivo}`);
return msg;

const err = msg.payload || 'Error desconocido';
node.error(`Error en backup: ${err}`);
node.status({ fill: 'red', shape: 'ring', text: 'ERROR backup' });
msg.query = `INSERT INTO audit_log (tipo, origen, mensaje)
    VALUES ('backup', 'sistema', 'ERROR en respaldo: ${String(err).replace(/'/g, "''")}');`;
return msg;
